  Ltac buf_prefix HK P0 Mq H17 :=
    let Hw0 := fresh "Hw0" in let Hw1 := fresh "Hw1" in let Hw2 := fresh "Hw2" in let Hw3 := fresh "Hw3" in
    krdv HK 0%nat (-592) 8%nat Hw0; [apply flat_intro; cbn [edenot ev ENV]; rewrite ?P0; lia|];
    krdv HK 0%nat (-584) 8%nat Hw1; [apply flat_intro; cbn [edenot ev ENV]; rewrite ?P0; lia|];
    krdv HK 0%nat (-576) 2%nat Hw2; [apply flat_intro; cbn [edenot ev ENV]; rewrite ?P0; lia|];
    krdv HK 0%nat (-574) 1%nat Hw3; [apply flat_intro; cbn [edenot ev ENV]; rewrite ?P0; lia|];
    unfold adenot, v_addi in Hw0, Hw1, Hw2, Hw3; cbn [a_base a_off edenot ev ENV] in Hw0, Hw1, Hw2, Hw3; rewrite P0 in Hw0, Hw1, Hw2, Hw3;
    assert (H17 : rdn RSEGS Mq (Z_to_bv 64 (bv_unsigned sp0 + -592)) 19 = Some PRE17);
    [ rewrite <- PRE17_words; change 19%nat with (8 + (8 + (2 + 1)))%nat;
      apply rdn_app_Z; [exact Hw0 | | lia | lia];
      apply rdn_app_Z; [ | | lia | lia];
      [ replace (bv_unsigned sp0 + -592 + Z.of_nat 8) with (bv_unsigned sp0 + -584) by lia; exact Hw1
      | apply rdn_app_Z; [ | | lia | lia];
        [ replace (bv_unsigned sp0 + -592 + Z.of_nat 8 + Z.of_nat 8) with (bv_unsigned sp0 + -576) by lia; exact Hw2
        | replace (bv_unsigned sp0 + -592 + Z.of_nat 8 + Z.of_nat 8 + Z.of_nat 2) with (bv_unsigned sp0 + -574) by lia; exact Hw3 ] ]
    | clear Hw0 Hw1 Hw2 Hw3 ].

